	/**
	 * Default Constructor
	 */
    public ExposureService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ExposureEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ExposureRepository.class) );
		this.validator		= applicationContext.getBean(ExposureValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Exposure
	 */
		public Exposure createExposure( CreateExposureCommand command ) {

		Exposure entity = new Exposure();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setExposureId( command.getExposureId() );
            entity.setExposureType( command.getExposureType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Exposure {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateExposureCommand
	 * @return		Exposure
	 */
	public Exposure updateExposure( UpdateExposureCommand command ) {

		Exposure entity = new Exposure();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setExposureId( command.getExposureId() );
            entity.setClaim( command.getClaim() );
            entity.setPolicyCoverage( command.getPolicyCoverage() );
            entity.setInsuredObject( command.getInsuredObject() );
            entity.setReserves( command.getReserves() );
            entity.setPayments( command.getPayments() );
            entity.setExposureType( command.getExposureType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Exposure {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteExposureCommand
	 */
	public void delete( DeleteExposureCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getExposureId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Exposure {0} ", id );

	}

	/**
	 * Method to retrieve the Exposure via ExposureFetchOneSummary
	 * @param 	summary ExposureFetchOneSummary
	 * @return 	ExposureFetchOneResponse
	 */
	public Exposure getExposure( ExposureFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ExposureFetchOneSummary arg cannot be null" );

		Exposure entity = null;
		UUID id = summary.getExposureId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Exposure using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Exposures
	 *
	 * @return 	List<Exposure>
	 */
    public List<Exposure> getAllExposure() {
		List<Exposure> list = projector.findAll( new FindAllExposureQuery() );
		return list;
	}

	/**
	 * assign Claim on Exposure
	 * @param		command AssignClaimToExposureCommand
	 */
	public void assignClaim( AssignClaimToExposureCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignClaim(command.getExposureId(), command.getAssignment());

	}

